var BrandKitsUpdate = &command.Spec{
	Group:          "brand",
	Name:           "kits update",
	Summary:        "Update Brand Kit",
	Description:    "Updates a brand kit's name or its role assignments — which color plays which part, which logo is the main one, and which font is used for headings and body text. A field you omit is left unchanged.\n\nCreation assigns these roles automatically, with no human in the loop, so this is how a caller corrects them.\n\nEach role object is replaced in full rather than merged: send the roles you want to keep, since a role you leave out of the object is cleared. Send an empty object to clear a role entirely. A cleared role stays cleared and is not recomputed later. Sending null for any field is rejected: omit it to leave it unchanged.\n\nRole edits require an assembled kit and return 409 while status is 'loading' or 'error'. Renaming is allowed at any time. Editing the colors themselves is not supported here yet.\n\nA brand kit shared into your workspace by another workspace is readable but not editable, and returns 403.",
	RequestSchema:  "{\n  \"description\": \"Request body for PATCH /v3/brand-kits/{brand_kit_id}.\\n\\nEvery field is optional and omitting one leaves it unchanged. Sending a role object with no\\nfields inside it (`{}`) clears that role, and a cleared role stays cleared — nothing recomputes\\nover a role the caller has deliberately emptied.\\n\\nClearing is an empty object rather than `null`, and `null` is rejected outright, so each\\nintention has exactly one spelling. Generated clients serialise request bodies with\\n`exclude_none` and drop a `null` before sending, so honouring `null` as \\\"clear\\\" would clear the\\nrole for a caller using raw HTTP and silently do nothing for a caller using our own SDK.\",\n  \"properties\": {\n    \"color_roles\": {\n      \"description\": \"Which color plays which part, as hex values. Replaces the stored assignment in full: a role you omit from this object is cleared, so send the roles you want to keep. Send `{}` to clear every color role.\",\n      \"properties\": {\n        \"accent\": {\n          \"description\": \"Accent color for highlights and calls to action, as a hex value.\",\n          \"nullable\": true,\n          \"type\": \"string\"\n        },\n        \"primary\": {\n          \"description\": \"Primary brand color, as a hex value like '#FF5733'.\",\n          \"nullable\": true,\n          \"type\": \"string\"\n        },\n        \"secondary\": {\n          \"description\": \"Secondary brand color, as a hex value.\",\n          \"nullable\": true,\n          \"type\": \"string\"\n        },\n        \"tertiary\": {\n          \"description\": \"Tertiary brand color, as a hex value.\",\n          \"nullable\": true,\n          \"type\": \"string\"\n        }\n      },\n      \"required\": [],\n      \"type\": \"object\"\n    },\n    \"font_roles\": {\n      \"description\": \"Which font plays which typographic part. Replaces the stored assignment in full, like color_roles.\",\n      \"properties\": {\n        \"body_text\": {\n          \"description\": \"Font for body copy.\",\n          \"nullable\": true,\n          \"properties\": {\n            \"font_id\": {\n              \"description\": \"Identifier of the font to assign. Not required to appear in the kit's `fonts` list: a role may legitimately name a font variant that the list does not enumerate separately.\",\n              \"nullable\": true,\n              \"type\": \"string\"\n            },\n            \"weight\": {\n              \"description\": \"Font weight, 1-1000. E.g. 400 for regular or 700 for bold.\",\n              \"nullable\": true,\n              \"type\": \"integer\"\n            }\n          },\n          \"required\": [],\n          \"type\": \"object\"\n        },\n        \"title_text\": {\n          \"description\": \"Font for headings and titles.\",\n          \"nullable\": true,\n          \"properties\": {\n            \"font_id\": {\n              \"description\": \"Identifier of the font to assign. Not required to appear in the kit's `fonts` list: a role may legitimately name a font variant that the list does not enumerate separately.\",\n              \"nullable\": true,\n              \"type\": \"string\"\n            },\n            \"weight\": {\n              \"description\": \"Font weight, 1-1000. E.g. 400 for regular or 700 for bold.\",\n              \"nullable\": true,\n              \"type\": \"integer\"\n            }\n          },\n          \"required\": [],\n          \"type\": \"object\"\n        }\n      },\n      \"required\": [],\n      \"type\": \"object\"\n    },\n    \"logo_roles\": {\n      \"description\": \"Which logo is the brand's main one. Replaces the stored assignment in full, like color_roles, so omitting `primary` clears it. Send `{}` to clear the logo role.\",\n      \"properties\": {\n        \"primary\": {\n          \"description\": \"Identifier of the primary logo. Must be a logo_id belonging to this kit that has finished importing.\",\n          \"nullable\": true,\n          \"type\": \"string\"\n        }\n      },\n      \"required\": [],\n      \"type\": \"object\"\n    },\n    \"name\": {\n      \"description\": \"New display name for the brand kit, 1-256 characters. Leading and trailing whitespace is trimmed.\",\n      \"type\": \"string\"\n    }\n  },\n  \"required\": [],\n  \"type\": \"object\"\n}",
	ResponseSchema: "{\n  \"properties\": {\n    \"data\": {\n      \"description\": \"A single brand kit with its colors, logos and fonts.\\n\\nA brand kit imported from a website is assembled in the background. While `status` is `loading`\\nthe collections and role fields are provisional and may be empty or incomplete; the import has\\nfinished contributing to them once `status` is `completed`. A kit whose import failed reports\\n`error` and keeps whatever was assembled before the failure. A kit can still be edited in the\\nHeyGen web app afterwards, so `completed` means the import is done, not that the kit is frozen.\",\n      \"properties\": {\n        \"brand_kit_id\": {\n          \"description\": \"Unique brand kit identifier.\",\n          \"type\": \"string\"\n        },\n        \"color_roles\": {\n          \"description\": \"Which color plays which part. May be absent while the kit is still loading.\",\n          \"nullable\": true,\n          \"properties\": {\n            \"accent\": {\n              \"description\": \"Accent color, used for highlights and calls to action.\",\n              \"nullable\": true,\n              \"type\": \"string\"\n            },\n            \"primary\": {\n              \"description\": \"Primary brand color.\",\n              \"nullable\": true,\n              \"type\": \"string\"\n            },\n            \"secondary\": {\n              \"description\": \"Secondary brand color.\",\n              \"nullable\": true,\n              \"type\": \"string\"\n            },\n            \"tertiary\": {\n              \"description\": \"Tertiary brand color.\",\n              \"nullable\": true,\n              \"type\": \"string\"\n            }\n          },\n          \"required\": [],\n          \"type\": \"object\"\n        },\n        \"colors\": {\n          \"description\": \"Brand colors as hex values, e.g. '#FF5733'. A color playing a role may sit outside this list — see color_roles — so do not treat it as the full set of colors the kit references.\",\n          \"items\": {\n            \"type\": \"string\"\n          },\n          \"type\": \"array\"\n        },\n        \"font_roles\": {\n          \"description\": \"Which font plays which typographic part. May be absent while the kit is still loading.\",\n          \"nullable\": true,\n          \"properties\": {\n            \"body_text\": {\n              \"description\": \"Font for body copy.\",\n              \"nullable\": true,\n              \"properties\": {\n                \"font_id\": {\n                  \"description\": \"Identifier of the assigned font.\",\n                  \"nullable\": true,\n                  \"type\": \"string\"\n                },\n                \"weight\": {\n                  \"description\": \"Font weight, e.g. 400 for regular or 700 for bold.\",\n                  \"nullable\": true,\n                  \"type\": \"integer\"\n                }\n              },\n              \"required\": [],\n              \"type\": \"object\"\n            },\n            \"title_text\": {\n              \"description\": \"Font for headings and titles.\",\n              \"nullable\": true,\n              \"properties\": {\n                \"font_id\": {\n                  \"description\": \"Identifier of the assigned font.\",\n                  \"nullable\": true,\n                  \"type\": \"string\"\n                },\n                \"weight\": {\n                  \"description\": \"Font weight, e.g. 400 for regular or 700 for bold.\",\n                  \"nullable\": true,\n                  \"type\": \"integer\"\n                }\n              },\n              \"required\": [],\n              \"type\": \"object\"\n            }\n          },\n          \"required\": [],\n          \"type\": \"object\"\n        },\n        \"fonts\": {\n          \"description\": \"Fonts belonging to the brand kit.\",\n          \"items\": {\n            \"description\": \"A font belonging to a brand kit.\",\n            \"properties\": {\n              \"font_id\": {\n                \"description\": \"Unique font identifier. A font_roles entry usually names one of these, but see font_roles for when it does not.\",\n                \"type\": \"string\"\n              },\n              \"name\": {\n                \"description\": \"Font family name.\",\n                \"nullable\": true,\n                \"type\": \"string\"\n              }\n            },\n            \"required\": [\n              \"font_id\"\n            ],\n            \"type\": \"object\"\n          },\n          \"type\": \"array\"\n        },\n        \"logo_roles\": {\n          \"description\": \"Which logo is the main one. May be absent while the kit is still loading.\",\n          \"nullable\": true,\n          \"properties\": {\n            \"primary\": {\n              \"description\": \"Identifier of the primary logo. Names a logo_id in `logos` unless that logo has since been deleted.\",\n              \"nullable\": true,\n              \"type\": \"string\"\n            }\n          },\n          \"required\": [],\n          \"type\": \"object\"\n        },\n        \"logos\": {\n          \"description\": \"Logos belonging to the brand kit.\",\n          \"items\": {\n            \"description\": \"A logo belonging to a brand kit.\",\n            \"properties\": {\n              \"logo_id\": {\n                \"description\": \"Unique logo identifier. The logo named by logo_roles.primary is the brand's main logo.\",\n                \"type\": \"string\"\n              },\n              \"name\": {\n                \"description\": \"Display name of the logo.\",\n                \"nullable\": true,\n                \"type\": \"string\"\n              },\n              \"url\": {\n                \"description\": \"URL of the logo image. Absent if the logo has no stored file yet.\",\n                \"nullable\": true,\n                \"type\": \"string\"\n              }\n            },\n            \"required\": [\n              \"logo_id\"\n            ],\n            \"type\": \"object\"\n          },\n          \"type\": \"array\"\n        },\n        \"name\": {\n          \"description\": \"Display name of the brand kit.\",\n          \"type\": \"string\"\n        },\n        \"status\": {\n          \"description\": \"Assembly status: 'loading' while the kit is still being built, 'completed' when it is ready, or 'error' if the import failed.\",\n          \"enum\": [\n            \"loading\",\n            \"completed\",\n            \"error\"\n          ],\n          \"type\": \"string\"\n        }\n      },\n      \"required\": [\n        \"brand_kit_id\",\n        \"name\",\n        \"status\"\n      ],\n      \"type\": \"object\"\n    }\n  },\n  \"required\": [],\n  \"type\": \"object\"\n}",
	Endpoint:       "/v3/brand-kits/{brand_kit_id}",
	Method:         "PATCH",
	BodyEncoding:   "json",
	Examples: []string{
		"# Rename a kit, leaving its role assignments untouched\n  heygen brand kits update <brand-kit-id> --name 'HeyGen brand'",
		"# Assign color roles (no flags for these, pass them via -d). Each role object is a full replace, so send every role you want to keep\n  heygen brand kits update <brand-kit-id> -d '{\"color_roles\":{\"primary\":\"#FF5733\",\"accent\":\"#1B998B\"}}'",
		"# Clear every color role, leaving the kit's colors themselves in place\n  heygen brand kits update <brand-kit-id> -d '{\"color_roles\":{}}'",
		"# See all available request fields\n  heygen brand kits update --request-schema",
	},
	Args: []command.ArgSpec{
		{Name: "brand-kit-id", Param: "brand_kit_id", Help: ""},
	},
	Flags: []command.FlagSpec{
		{
			Name:     "name",
			Type:     "string",
			Default:  "",
			Help:     "New display name for the brand kit, 1-256 characters. Leading and trailing whitespace is trimmed.",
			Required: false,
			Enum:     nil,
			Min:      nil,
			Max:      nil,
			Source:   "body",
			JSONName: "name",
		},
	},
}
